package main

import (
	"context"
	"fmt"

	"example.com/lib"
)

// greeting wraps the library call so tests do not depend on its signature.
func greeting(name string) string {
	return lib.Greet(context.Background(), name)
}

func main() {
	fmt.Println(greeting("steward"), farewell("steward"))
}

package main

import (
	"context"

	"example.com/lib"
)

// farewell is a second call site in a second file.
func farewell(name string) string {
	return "bye, " + lib.Greet(context.Background(), name)
}
